INSERT INTO "standard" ("id","std_no","name_cn","name_en","stage_code","std_type","tc_wg","responsible_authority","leading_org","risk_level","mb_owner","planned_release_date","actual_release_date","effective_date","scope","archived_at","archived_by","created_at","created_by","updated_at","updated_by") VALUES (7,'GB/T 38834.1-2020','机器人 服务机器人性能规范及其试验方法 第1部分：轮式机器人运动','Robotics—Performance criteria and related test methods for service robots—Part 1: Locomotion for wheeled robots','REEXAMINATION','GB/T','全国机器人标准化技术委员会','全国机器人标准化技术委员会','北京机械工业自动化研究所有限公司','Medium','叶知秋',NULL,'2020-06-02','2020-12-01','跟踪重点：轮式移动性能试验条件；负载与地面条件记录。试验记录统一填写负载、地面材质、电量、轮胎状态及路线，分别报告直行与转弯表现。',NULL,NULL,'2019-06-08 09:00:00','叶知秋','2026-10-02 16:30:00','叶知秋');
INSERT INTO "standard" ("id","std_no","name_cn","name_en","stage_code","std_type","tc_wg","responsible_authority","leading_org","risk_level","mb_owner","planned_release_date","actual_release_date","effective_date","scope","archived_at","archived_by","created_at","created_by","updated_at","updated_by") VALUES (15,'GB/T 47494-2026','物流机器人 电气安全要求','Logistics robots—Requirements for electrical safety','RELEASED','GB/T','全国机器人标准化技术委员会','全国机器人标准化技术委员会','杭州海康机器人股份有限公司','High','许清禾',NULL,'2026-04-30','2026-11-01','跟踪重点：物流机器人实施准备；充电与电气保护配置。逐机型复核电气图纸、接地连接、充电接口和保护装置，形成实施前差距与整改清单。',NULL,NULL,'2025-05-05 09:00:00','叶知秋','2026-10-02 16:30:00','叶知秋');
INSERT INTO "standard" ("id","std_no","name_cn","name_en","stage_code","std_type","tc_wg","responsible_authority","leading_org","risk_level","mb_owner","planned_release_date","actual_release_date","effective_date","scope","archived_at","archived_by","created_at","created_by","updated_at","updated_by") VALUES (17,'GB/T 47495-2026','物流机器人 电气安全测试方法','Logistics robots—Test methods for electrical safety','APPROVAL_DRAFT','GB/T','全国机器人标准化技术委员会','全国机器人标准化技术委员会','北京机械工业自动化研究所有限公司','High','沈可欣','2027-04-30',NULL,NULL,'跟踪重点：物流电气试验能力建设；试验设备与记录模板。梳理试验设备、夹具、测量范围与记录模板，确认新旧设备的适用性和校准有效期。',NULL,NULL,'2025-08-19 09:00:00','叶知秋','2026-10-02 16:30:00','叶知秋');
INSERT INTO "standard" ("id","std_no","name_cn","name_en","stage_code","std_type","tc_wg","responsible_authority","leading_org","risk_level","mb_owner","planned_release_date","actual_release_date","effective_date","scope","archived_at","archived_by","created_at","created_by","updated_at","updated_by") VALUES (21,'GB/T 45271-2026','人形机器人 通用安全要求','Humanoid robots—General safety requirements','COMMENT_DRAFT','GB/T','全国机器人标准化技术委员会人形机器人工作组','全国机器人标准化技术委员会','机器人安全联合研究组','High','周启明','2027-06-30',NULL,NULL,'模拟跟踪人形机器人机械、电气、功能安全及人机协作风险控制要求。',NULL,NULL,'2026-10-10 17:30:00','标准事务组','2026-10-10 17:30:00','标准事务组');
INSERT INTO "standard" ("id","std_no","name_cn","name_en","stage_code","std_type","tc_wg","responsible_authority","leading_org","risk_level","mb_owner","planned_release_date","actual_release_date","effective_date","scope","archived_at","archived_by","created_at","created_by","updated_at","updated_by") VALUES (22,'GB/T 45288-2026','移动机器人 导航与定位性能试验方法','Mobile robots—Test methods for navigation and localization performance','REVIEW_DRAFT','GB/T','全国机器人标准化技术委员会移动机器人工作组','全国机器人标准化技术委员会','智能移动装备测试联合组','Medium','叶知秋','2027-03-31',NULL,NULL,'模拟跟踪定位精度、重复性、动态避障和复杂场景试验方法。',NULL,NULL,'2026-10-10 17:30:00','标准事务组','2026-10-10 17:30:00','标准事务组');
